package remframework.measurement.compact;

import org.joml.Vector3i;
import remframework.measurement.detector.IsotropyReferenceGeometry;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

/** Finalizes measured compact-backend CSV/SVG outputs without changing data. */
public final class CompactOutputFinalizer {
    private static final double ORIENTATION_TOLERANCE = 1e-12;
    private record S(String axis,String direction,int shell,double mean,double variation) { }
    private CompactOutputFinalizer() { }

    public static void main(String[] args) throws Exception {
        if (args.length != 1) throw new IllegalArgumentException("Usage: CompactOutputFinalizer <output-directory>");
        finalize(Path.of(args[0]).toAbsolutePath().normalize());
    }

    public static void finalize(Path out) throws IOException {
        Map<String,List<S>> all=new LinkedHashMap<>();
        for(String axis:List.of("X","Y","Z")) for(S s:read(out,axis)) all.computeIfAbsent(axis+":"+s.shell,k->new ArrayList<>()).add(s);
        writeIsotropy(out,all); writeComparison(out,all); writeSvgs(out,all);
    }

    private static List<S> read(Path out,String axis)throws IOException { List<S> r=new ArrayList<>(); List<String> lines=Files.readAllLines(out.resolve("stable-cycle-detector-summary-"+axis+".csv")); for(String line:lines.subList(1,lines.size())){if(line.isBlank())continue;String[]v=line.split(",",-1);r.add(new S(axis,v[1],Integer.parseInt(v[2]),Double.parseDouble(v[3]),Double.parseDouble(v[5])));}return r; }
    private static void writeIsotropy(Path out,Map<String,List<S>> all)throws IOException { try(BufferedWriter w=Files.newBufferedWriter(out.resolve("stable-cycle-isotropy-summary.csv"))){w.write("oscillatorAxis,graphShell,detectorCount,meanResponse,Emax,MAD,StdDev,strongestDirection,strongestQ,weakestDirection,weakestQ,maxCycleVariation,meanCycleVariation\n");for(String axis:List.of("X","Y","Z"))for(int shell:IsotropyReferenceGeometry.SHELLS){List<S>a=all.get(axis+":"+shell);double mean=a.stream().mapToDouble(s->s.mean).average().orElse(Double.NaN);double e=Double.NaN,mad=Double.NaN,sd=Double.NaN,hi=Double.NaN,lo=Double.NaN;String hd="",ld="";if(Double.isFinite(mean)&&mean!=0){List<Double>q=a.stream().map(s->s.mean/mean).toList();e=q.stream().mapToDouble(x->Math.abs(x-1)).max().orElse(Double.NaN);mad=q.stream().mapToDouble(x->Math.abs(x-1)).average().orElse(Double.NaN);sd=Math.sqrt(q.stream().mapToDouble(x->(x-1)*(x-1)).average().orElse(Double.NaN));int h=0,l=0;for(int i=1;i<q.size();i++){if(q.get(i)>q.get(h))h=i;if(q.get(i)<q.get(l))l=i;}hd=a.get(h).direction;ld=a.get(l).direction;hi=q.get(h);lo=q.get(l);}double maxVar=a.stream().mapToDouble(s->s.variation).filter(Double::isFinite).max().orElse(Double.NaN),meanVar=a.stream().mapToDouble(s->s.variation).filter(Double::isFinite).average().orElse(Double.NaN);w.write(String.format(Locale.ROOT,"%s,%d,%d,%.17g,%.17g,%.17g,%.17g,%s,%.17g,%s,%.17g,%.17g,%.17g\n",axis,shell,a.size(),mean,e,mad,sd,hd,hi,ld,lo,maxVar,meanVar));}} }
    private static void writeComparison(Path out,Map<String,List<S>> all)throws IOException{Map<String,String>ids=new HashMap<>();for(int i=0;i<IsotropyReferenceGeometry.RAYS.size();i++){Vector3i r=IsotropyReferenceGeometry.RAYS.get(i);ids.put(key(r.x,r.y,r.z),"R"+String.format("%02d",i+1));}String[]from={"X","X","Y"},to={"Y","Z","Z"},labels={"(x,y,z)->(y,x,z)","(x,y,z)->(z,y,x)","(x,y,z)->(x,z,y)"};int[][]p={{1,0,2},{2,1,0},{0,2,1}};try(BufferedWriter w=Files.newBufferedWriter(out.resolve("oscillator-orientation-comparison.csv"))){w.write("fromAxis,toAxis,graphShell,permutation,matchedDetectorCount,maximumAbsoluteDifference,meanAbsoluteDifference,tolerance,withinTolerance\n");for(int k=0;k<3;k++)for(int shell:IsotropyReferenceGeometry.SHELLS){Map<String,S>a=map(all.get(from[k]+":"+shell)),b=map(all.get(to[k]+":"+shell));List<Double>d=new ArrayList<>();for(Vector3i r:IsotropyReferenceGeometry.RAYS){String s=ids.get(key(r.x,r.y,r.z)),t=ids.get(key(component(r,p[k][0]),component(r,p[k][1]),component(r,p[k][2])));if(t!=null&&a.containsKey(s)&&b.containsKey(t))d.add(Math.abs(a.get(s).mean-b.get(t).mean));}double max=d.stream().mapToDouble(x->x).max().orElse(Double.NaN),mean=d.stream().mapToDouble(x->x).average().orElse(Double.NaN);w.write(String.format(Locale.ROOT,"%s,%s,%d,%s,%d,%.17g,%.17g,%.1e,%s\n",from[k],to[k],shell,labels[k],d.size(),max,mean,ORIENTATION_TOLERANCE,Double.isFinite(max)&&max<=ORIENTATION_TOLERANCE));}}}
    private static void writeSvgs(Path out,Map<String,List<S>> all)throws IOException{StringBuilder response=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1600\" height=\"900\"><text x=\"20\" y=\"25\">Measured normalized response by exact primitive direction; ideal Q=1</text>");int y=50;for(String axis:List.of("X","Y","Z"))for(int shell:IsotropyReferenceGeometry.SHELLS){List<S>a=all.get(axis+":"+shell);double m=a.stream().mapToDouble(s->s.mean).average().orElse(Double.NaN);response.append("<text x=\"20\" y=\"").append(y).append("\"> ").append(axis).append(" D=").append(shell).append(" ");for(S s:a)response.append(s.direction).append("=").append(m==0?"NaN":s.mean/m).append(" ");response.append("</text>");y+=22;}response.append("</svg>\n");Files.writeString(out.resolve("isotropy-response-by-direction.svg"),response.toString());StringBuilder error=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1200\" height=\"700\"><text x=\"20\" y=\"25\">Measured Emax versus graph distance</text>");y=50;for(String axis:List.of("X","Y","Z")){error.append("<text x=\"20\" y=\"").append(y).append("\">").append(axis).append(": ");for(int shell:IsotropyReferenceGeometry.SHELLS){List<S>a=all.get(axis+":"+shell);double m=a.stream().mapToDouble(s->s.mean).average().orElse(Double.NaN);error.append("D").append(shell).append("=").append(m==0?"NaN":a.stream().mapToDouble(s->Math.abs(s.mean/m-1)).max().orElse(Double.NaN)).append(" ");}error.append("</text>");y+=24;}error.append("</svg>\n");Files.writeString(out.resolve("isotropy-error-vs-graph-distance.svg"),error.toString());StringBuilder stability=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1200\" height=\"700\"><text x=\"20\" y=\"25\">Measured individual responses for cycles 6..11</text>");y=50;for(String axis:List.of("X","Y","Z")){stability.append("<text x=\"20\" y=\"").append(y).append("\">").append(axis).append(" R01 D24: ");for(String line:Files.readAllLines(out.resolve("stable-cycle-detector-results-"+axis+".csv")))if(line.startsWith(axis+",R01,\"(1,0,0)\",24,"))stability.append(line.substring(line.lastIndexOf(',')+1)).append(" ");stability.append("</text>");y+=24;}stability.append("</svg>\n");Files.writeString(out.resolve("cycle-stability.svg"),stability.toString());Files.writeString(out.resolve("oscillator-orientation-comparison.svg"),"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1200\" height=\"700\"><text x=\"20\" y=\"25\">Measured oscillator orientation comparison; tolerance 1e-12</text><text x=\"20\" y=\"55\">See oscillator-orientation-comparison.csv for shell-level values.</text></svg>\n");}
    private static Map<String,S> map(List<S> a){Map<String,S>m=new HashMap<>();for(S s:a)m.put(s.direction,s);return m;}
    private static String key(int x,int y,int z){return x+":"+y+":"+z;}
    private static int component(Vector3i r,int n){return n==0?r.x:n==1?r.y:r.z;}
}
